import { action, addCommonDatenfelderSearchOptions, choiceOption, commonDatenfelderParams, parseNonEmpty, renderJson, renderRaw, } from "../shared.js";
import { GruppeSucheInValues } from "@maschinenlesbar.org/fim-portal-client/internal/enums";
export function registerGroupCommands(program, deps) {
    const groups = program.command("groups").description("Datenfeldgruppen (data groups)");
    const search = groups
        .command("search")
        .description("Search/filter data groups")
        .addOption(choiceOption("--suche-nur-in <module>", "restrict full-text search to a module", GruppeSucheInValues));
    addCommonDatenfelderSearchOptions(search).action(action(deps, async ({ client, global, opts }) => {
        const params = {
            ...commonDatenfelderParams(opts),
            suche_nur_in: opts["sucheNurIn"],
        };
        renderJson(deps, global, await client.groups.search(params));
    }));
    groups
        .command("versions")
        .argument("<namespace>", "namespace of the element", parseNonEmpty)
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .description("List all versions of a data group")
        .action(action(deps, async ({ client, global }, [namespace, fimId]) => {
        renderJson(deps, global, await client.groups.versions(namespace, fimId));
    }));
    groups
        .command("get")
        .argument("<namespace>", "namespace of the element", parseNonEmpty)
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Get a single data group (version defaults to 'latest')")
        .action(action(deps, async ({ client, global }, [namespace, fimId, fimVersion]) => {
        renderJson(deps, global, await client.groups.get(namespace, fimId, fimVersion ?? "latest"));
    }));
    groups
        .command("xdf")
        .argument("<namespace>", "namespace of the element", parseNonEmpty)
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Download the XDatenfelder XML for a data group")
        .action(action(deps, async ({ client, global }, [namespace, fimId, fimVersion]) => {
        await renderRaw(deps, global, await client.groups.downloadXdf(namespace, fimId, fimVersion ?? "latest"));
    }));
}
